// Creates the logo files for the Microsoft Store package (build/appx) and the 300x300 Store listing icon (store/assets).
// Source: build/icon.png. Run with `npm run store:assets`.
import sharp from 'sharp';
import { mkdir } from 'node:fs/promises';

await mkdir('build/appx', { recursive: true });
await mkdir('store/assets', { recursive: true });

const icon = 'build/icon.png';
const square = (size, out) => sharp(icon).resize(size, size).png({ compressionLevel: 9 }).toFile(out);

// Names and sizes are what the AppX manifest generated by electron-builder refers to.
await square(50, 'build/appx/StoreLogo.png');
await square(44, 'build/appx/Square44x44Logo.png');
await square(150, 'build/appx/Square150x150Logo.png');

// Wide tile: the icon centered on the app's dark background.
const wideIcon = await sharp(icon).resize(120, 120).toBuffer();
await sharp({ create: { width: 310, height: 150, channels: 4, background: '#1b1d22' } })
  .composite([{ input: wideIcon, gravity: 'center' }])
  .png({ compressionLevel: 9 })
  .toFile('build/appx/Wide310x150Logo.png');

// Store listing: 1:1 app tile icon (300 x 300).
await square(300, 'store/assets/app-tile-icon-300x300.png');

console.log('wrote build/appx/*.png and store/assets/app-tile-icon-300x300.png');
